    if (inst.type === "Z") {
      return null;
    }
    if (inst.type === "H" || inst.type === "V") {
      return null;
    }
    const topLeft = [inst.x - 5, inst.y - 5];
    const topRight = [inst.x + 5, inst.y - 5];
    const bottomLeft = [inst.x - 5, inst.y + 5];
    const bottomRight = [inst.x + 5, inst.y + 5];
