      {
        type: "M",
        x: topLeft[0],
        y: topLeft[1]
      },
      {
        type: "L",
        x: topRight[0],
        y: topRight[1]
      },
      {
        type: "L",
        x: bottomRight[0],
        y: bottomRight[1]
      },
      {
        type: "L",
        x: bottomLeft[0],
        y: bottomLeft[1]
      },
      {
        type: "Z"
      }
